import{_ as e,o as a,c as r,ah as o}from"./chunks/framework.DDXs_i7t.js";const p=JSON.parse('{"title":"Christian Mattura & the Pilnacek Tape","description":"","frontmatter":{},"headers":[],"relativePath":"en/recherche/christian-mattura-pilnacek-tape.md","filePath":"en/recherche/christian-mattura-pilnacek-tape.md"}'),i={name:"en/recherche/christian-mattura-pilnacek-tape.md"};function n(h,t,s,c,u,l){return a(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="christian-mattura-the-pilnacek-tape" tabindex="-1">Christian Mattura &amp; the Pilnacek Tape <a class="header-anchor" href="#christian-mattura-the-pilnacek-tape" aria-label="Permalink to &quot;Christian Mattura &amp; the Pilnacek Tape&quot;">​</a></h1><p><strong>Status:</strong> Actively Researched (as of March 12, 2026)<br><strong>Role:</strong> Key Witness of Acoustic Forensics<br><strong>Significance:</strong> Originator of the secret recording of Christian Pilnacek</p><hr><h2 id="🎙️-the-pilnacek-tape-22-minutes-of-truth" tabindex="-1">🎙️ The &quot;Pilnacek Tape&quot;: 22 Minutes of Truth <a class="header-anchor" href="#🎙️-the-pilnacek-tape-22-minutes-of-truth" aria-label="Permalink to &quot;🎙️ The &quot;Pilnacek Tape&quot;: 22 Minutes of Truth&quot;">​</a></h2><p>In November 2023, a 22-minute audio recording was released to the public, shaking the foundations of the Austrian political system. The recording was made in a Vienna restaurant (&quot;Prinz Eugen&quot;) and shows a Christian Pilnacek complaining about the massive pressure exerted on him and the judiciary by the ÖVP.</p><h3 id="central-quotes-from-the-tape" tabindex="-1"><strong>Central Quotes from the Tape:</strong> <a class="header-anchor" href="#central-quotes-from-the-tape" aria-label="Permalink to &quot;**Central Quotes from the Tape:**&quot;">​</a></h3><blockquote><p><em>&quot;The ÖVP is not my party. They are not democrats.&quot;</em><em>&quot;Who has tormented me the most? The ÖVP!&quot;</em><em>&quot;Sobotka is the worst of them all.&quot;</em></p></blockquote><hr><h2 id="👤-who-is-christian-mattura" tabindex="-1">👤 Who is Christian Mattura? <a class="header-anchor" href="#👤-who-is-christian-mattura" aria-label="Permalink to &quot;👤 Who is Christian Mattura?&quot;">​</a></h2><p>Christian Mattura is an Austrian entrepreneur and lobbyist (formerly in the gambling sector). He is the person who secretly recorded the conversation with Pilnacek.</p><h3 id="motivation-according-to-mattura" tabindex="-1"><strong>Motivation according to Mattura:</strong> <a class="header-anchor" href="#motivation-according-to-mattura" aria-label="Permalink to &quot;**Motivation according to Mattura:**&quot;">​</a></h3><p>In the inquiry committee on March 12, 2026, he stated that he had made the recording to &quot;finally change the system.&quot; He experienced Pilnacek as a broken man suffering under the weight of political interventions.</p><hr><h2 id="⚖️-the-match-in-the-inquiry-committee-march-12-2026" tabindex="-1">⚖️ The &quot;Match&quot; in the Inquiry Committee (March 12, 2026) <a class="header-anchor" href="#⚖️-the-match-in-the-inquiry-committee-march-12-2026" aria-label="Permalink to &quot;⚖️ The &quot;Match&quot; in the Inquiry Committee (March 12, 2026)&quot;">​</a></h2><p>During his questioning, an unprecedented exchange with the ÖVP occurred:</p><ul><li><strong>Hanger Scale:</strong> Mattura directly attacked Andreas Hanger (ÖVP) for his discrediting tactics.</li><li><strong>The Laptop:</strong> Mattura brought new statements into play about attempts to make Pilnacek&#39;s laptop &quot;disappear.&quot;</li><li><strong>Credibility:</strong> The ÖVP attempts to portray Mattura as untrustworthy due to his business past – a classic maneuver of &quot;Hard Prose.&quot;</li></ul><hr><h2 id="🎬-relevance-for-the-horten-mystery" tabindex="-1">🎬 Relevance for &quot;The Horten Mystery&quot; <a class="header-anchor" href="#🎬-relevance-for-the-horten-mystery" aria-label="Permalink to &quot;🎬 Relevance for &quot;The Horten Mystery&quot;&quot;">​</a></h2><p>In our mockumentary, Christian Mattura serves as a model for the character of the <strong>&quot;Chronicler of the Secret.&quot;</strong></p><ul><li><strong>Motiv:</strong> The aesthetics of the secret recording.</li><li><strong>Part 4:</strong> We will cinematically reconstruct the scene in the restaurant to make the &quot;coldness of intervention&quot; palpable.</li></ul><hr><p>👈 <a href="/en/recherche/postenschacher.html">Back to Research Overview</a></p>',22)])])}const d=e(i,[["render",n]]);export{p as __pageData,d as default};
